//go:build ignore

// Copy into upstream converter/xlsx and run TestCodexXLSXGeometry.
package xlsx
import("archive/zip";"bytes";"encoding/json";"fmt";"math/rand";"os";"path/filepath";"testing")
func TestCodexXLSXGeometry(t *testing.T){root:=os.Getenv("BDF_FIXTURE_ROOT");if root==""{t.Fatal("BDF_FIXTURE_ROOT required")};samples:=[][]byte{};for _,name:=range []string{"basic.xlsx","features.xlsx","form-fixed.xlsx","form-pages.xlsx","form-rows.xlsx","math.xlsx","print.xlsx"}{b,e:=os.ReadFile(filepath.Join("testdata",name));if e!=nil{t.Fatal(e)};samples=append(samples,b)};r:=rand.New(rand.NewSource(936422));for i:=0;i<1300;i++{var b bytes.Buffer;z:=zip.NewWriter(&b);add:=func(name,content string){f,e:=z.Create(name);if e!=nil{t.Fatal(e)};f.Write([]byte(content))};add("xl/workbook.xml",`<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="S" r:id="rId1"/></sheets></workbook>`);add("xl/_rels/workbook.xml.rels",`<Relationships><Relationship Id="rId1" Type="x/worksheet" Target="worksheets/sheet1.xml"/></Relationships>`);s:=`<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">`;if i%3!=0{s+=fmt.Sprintf(`<sheetViews><sheetView showGridLines="%d" showZeros="%d" rightToLeft="%d"><pane state="%s" xSplit="%d" ySplit="%d"/></sheetView></sheetViews>`,r.Intn(2),r.Intn(2),r.Intn(2),[]string{"split","frozen","frozenSplit"}[r.Intn(3)],r.Intn(6),r.Intn(8))};if i%5!=0{s+=fmt.Sprintf(`<sheetFormatPr defaultColWidth="%.1f" baseColWidth="%.1f" defaultRowHeight="%.1f" zeroHeight="%d"/>`,float64(r.Intn(3000))/10,float64(r.Intn(3000))/10,float64(r.Intn(6000))/10,r.Intn(2))};s+="<cols>";for j:=0;j<r.Intn(8);j++{s+=fmt.Sprintf(`<col min="%d" max="%d" width="%.1f" hidden="%d" style="%d"/>`,r.Intn(9),r.Intn(9),float64(r.Intn(3000))/10,r.Intn(2),r.Intn(8))};s+="</cols><mergeCells>";for j:=0;j<r.Intn(6);j++{s+=`<mergeCell ref="`+[]string{"A1:C3","B2","C3:A1","A:C","3:5","bad","XFD1:XFD2"}[r.Intn(7)]+`"/>`};s+=`</mergeCells><autoFilter ref="`+[]string{"A1:D9","B:C","bad","2:5"}[r.Intn(4)]+`"/><sheetData/></worksheet>`;add("xl/worksheets/sheet1.xml",s);if e:=z.Close();e!=nil{t.Fatal(e)};samples=append(samples,append([]byte{},b.Bytes()...))};out:=[]any{};for _,data:=range samples{c,_,e:=openWorkbook(bytes.NewReader(data),int64(len(data)),&Options{NoSystemFonts:true,SystemFonts:true});if e!=nil{t.Fatal(e)};for _,sheet:=range c.sheets{if sheet.chart{continue};ws,e:=c.readWorksheet(sheet.part);if e!=nil{t.Fatal(e)};cols:=[]any{};for _,v:=range ws.cols{cols=append(cols,[]any{v.min,v.max,v.width,v.hidden,v.style})};merges:=[]any{};for _,v:=range ws.merges{merges=append(merges,[]any{v.r0,v.c0,v.r1,v.c1})};var filter any;if v:=ws.autoFilter;v!=nil{filter=[]any{v.r0,v.c0,v.r1,v.c1}};out=append(out,map[string]any{"input":data,"part":sheet.part,"want":[]any{ws.defColW,ws.baseColW,ws.defRowH,ws.zeroH,ws.showGrid,ws.showZero,ws.rtl,ws.freezeC,ws.freezeR,cols,merges,filter}})}};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/xlsx/geometry.json"),b,0644);e!=nil{t.Fatal(e)}}
